mapper.update:
UPDATE tb_node
SET node_id = #{nodeDto.afterNodeId}
WHERE node_id = #{nodeDto.nodeId}

mapper.select:
SELECT id as id, node_id as nodeId, node_type as nodeType,stack as stack
FROM tb_node
WHERE status != '1'

    and node_id like concat(concat('%', #{nodeDto.nodeId}), '%')


    and node_type = #{nodeDto.nodeType}


    and site_id = #{nodeDto.siteId}

SELECT count(*)
FROM tb_node
WHERE node_id = #{nodeId}

SELECT count(1)
FROM tb_node
WHERE node_id = #{nodeId}


    SELECT t.id as id , t.nodeId as nodeId,t.stackId as stackId, t.nodeType as nodeType,t.gatherSite gatherSite from (

select id id,node_id nodeId,stack_id stackId ,node_type nodeType ,gather_site gatherSite from tb_node tnode


        and site_route like concat(concat('%', #{monitorCondition.pidRoute}),'%')


        and node_type in

            #{nodeType}



        and site_type = #{monitorCondition.siteType}

    and status = 1

order by site_route,site_x,site_y,site_z
) t where t.stackId in #{stackId}

select id, type, ${tableColumn},transfer_time as transferTime,node_id nodeId, frequency, voltage, signal_strength signalStrength, stack_id stackId, maintain_plan_id maintainPlanId, maintain_stage_id maintainStageId, gather_site gatherSite, site_type siteType, alert_level alertLevel, pid_route siteRoute, site_x siteX, site_y siteY,
temp_level tempLevel, humidity_level humidityLevel,
site_z siteZ from ${tableName} where node_id in #{nodeDto.nodeId} and transfer_time >=#{nodeDto.startTime} and maintain_plan_id >=#{nodeDto.maintainPlanId}
and maintain_stage_id >=#{nodeDto.maintainStage}
and pid_route =#{pidRoute} and transfer_time <=#{nodeDto.endTime} ORDER BY transfer_time

select status
from tb_node
where id = #{id}

select node_type as "nodeType",node_id as "nodeId" from tb_node where site_type = #{siteType}
and stack_id = #{stackId}
and site_route = #{pidRoute}

SELECT node_id AS nodeId, site_route siteRoute, node_type nodeType, gather_site gatherSite FROM tb_node WHERE node_type in
#{nodeType}
AND site_route like concat (concat ('%',#{monitorCondition.pidRoute}),'%')
AND site_type = #{monitorCondition.siteType}
AND status = 1 order by siteRoute

select *
from (select ${tableColumn}    as node,
             transfer_time     as transferTime
      from ${tableName}
      where node_id = #{nodeId}
     order by transfer_time Desc limit 10)
order by transferTime asc

select oxygen,node_id as nodeId,material_code as materialCode,pid_route as siteRoute from tb_node_o2_history where (transfer_time,node_id) in (select max(transfer_time),node_id from tb_node_o2_history where 1=1 and pid_route in
#{siteRoute}
group by node_id)

select ${column},node_id as nodeId,material_code as materialCode,pid_route as siteRoute from ${tableName} where (transfer_time,node_id) in (select max(transfer_time),node_id from ${tableName} where site_type = '05' and pid_route in
#{siteRoute}
group by node_id)

select ${column},any(node_id) as nodeId,any(material_code) as materialCode,pid_route as siteRoute from ${tableName} where (transfer_time,node_id) in (select max(transfer_time),node_id from ${tableName} where site_type = '04' and pid_route in
#{siteRoute}
group by node_id) group by pid_route

select round(avg(${columnOne}),1) as "data",${gatherType} as "dayTime" from ${tableColumn} where node_id = #{nodeId}
and transfer_time >= #{startTime}
and transfer_time <= #{endTime}
group by dayTime

select round(avg(${columnOne}),1) as "data",${gatherType} as "dayTime" from ${tableColumn} where pid_route =
#{siteRoute}
and transfer_time >= #{startTime}
and transfer_time <= #{endTime}
group by dayTime

select ifNotFinite(avg(temp),0) as "temp",ifNotFinite(avg(humiture),0) as "humiture" from tb_air_conditioner_history where (node_id,transfer_time) in (select node_id,max(transfer_time) from tb_air_conditioner_history where node_id in
#{nodeId}
group by node_id)

select node_type nodeType
from tb_node
where id = #{id}
  and node_id = #{nodeId}

select pid_route "pidRoute",gather_site "gatherSite" ,toString(toStartOfDay(createdTime)) ,toString(toStartOfWeek(createdTime)) as "dateTime" , floor(AVG(oxygen),2) "avgOxygen",MAX(oxygen) "maxOxygen",MIN(oxygen) "minOxygen"
, floor(AVG(temp),2) "avgTemp",MAX(temp) "maxTemp",MIN(temp) "minTemp" , floor(AVG(humiture),2) "avgHumiture",MAX(humiture) "maxHumiture",MIN(humiture) "minHumiture"
, floor(AVG(temp),2) "avgCoreTemp",MAX(temp) "maxCoreTemp",MIN(temp) "minCoreTemp"
from ${tableName}
and pid_route in
#{item}
and createdTime >= #{beginTime}
and createdTime <= #{endTime}
group by pid_route,gather_site ,toStartOfDay(createdTime) ,toStartOfWeek(createdTime) order by dateTime

select distinct node_id from tb_node_temp_core_history where transfer_time between #{begin} and #{end}
union all
select distinct node_id from tb_node_o2_history  where transfer_time between #{begin} and #{end}
union all
select distinct node_id from tb_node_env_history  where transfer_time between #{begin} and #{end}
